sp_page.css:
/* =========================================================
   MEALCARE — PAGE CSS
   Premium ServiceNow / Hackathon Presentation
   HTML UNCHANGED
   ========================================================= */

html,
body {
  margin: 0 !important;
  padding: 0 !important;

  background: #F5F7F3 !important;
  color: #173B38;

  font-family:
    Inter,
    "Segoe UI",
    Roboto,
    Arial,
    sans-serif;

  overflow-x: hidden !important;

  scroll-behavior: smooth;

  -webkit-font-smoothing: antialiased;
}


/* =========================================================
   SERVICENOW PAGE RESET
   ========================================================= */

body,
.sp-page-root,
.page,
.main-content,
.sp-content,
.sp-page-root .container,
.sp-page-root .container-fluid {
  margin: 0 !important;
  padding: 0 !important;

  width: 100% !important;
  max-width: none !important;

  background: #F5F7F3 !important;
}


/* =========================================================
   REMOVE DEFAULT SERVICE NOW ROW GAPS
   ========================================================= */

.sp-page-root .row,
.main-content .row {
  margin-left: 0 !important;
  margin-right: 0 !important;
}


/* =========================================================
   FULL-WIDTH MEALCARE SECTIONS
   ========================================================= */

.cfa-hero,
.cfa-welcome,
.cfa-services,
.cfa-about,
.cfa-contact {

  width: 100vw !important;
  max-width: none !important;

  margin-left:
    calc(50% - 50vw) !important;

  margin-right:
    calc(50% - 50vw) !important;

  box-sizing: border-box;

  overflow: hidden;

  position: relative;
}


/* =========================================================
   ANCHOR POSITION
   Prevent ServiceNow navbar overlap
   ========================================================= */

#home,
#services,
#about,
#contact {
  scroll-margin-top: 90px;
}


/* =========================================================
   GLOBAL BOX SIZING
   ========================================================= */

.cfa-hero *,
.cfa-welcome *,
.cfa-services *,
.cfa-about *,
.cfa-contact *,
.cfa-hero *::before,
.cfa-welcome *::before,
.cfa-services *::before,
.cfa-about *::before,
.cfa-contact *::before,
.cfa-hero *::after,
.cfa-welcome *::after,
.cfa-services *::after,
.cfa-about *::after,
.cfa-contact *::after {

  box-sizing: border-box;
}


/* =========================================================
   SELECTION
   ========================================================= */

::selection {
  background: #123C3A;
  color: #F7C56F;
}


/* =========================================================
   SCROLLBAR
   ========================================================= */

::-webkit-scrollbar {
  width: 8px;
}

::-webkit-scrollbar-track {
  background: #E9EFEB;
}

::-webkit-scrollbar-thumb {
  background: #123C3A;
  border-radius: 20px;
}

::-webkit-scrollbar-thumb:hover {
  background: #E89B3C;
}


/* =========================================================
   ACCESSIBILITY
   ========================================================= */

a:focus-visible,
button:focus-visible {
  outline:
    3px solid #E89B3C !important;

  outline-offset: 4px;

  border-radius: 6px;
}


/* =========================================================
   MOBILE
   ========================================================= */

@media (max-width: 767px) {

  .cfa-hero,
  .cfa-welcome,
  .cfa-services,
  .cfa-about,
  .cfa-contact {

    width: 100% !important;

    margin-left: 0 !important;
    margin-right: 0 !important;
  }

}


@media (prefers-reduced-motion: reduce) {

  html {
    scroll-behavior: auto !important;
  }

  *,
  *::before,
  *::after {
    animation-duration: 0.01ms !important;
    animation-iteration-count: 1 !important;
    transition-duration: 0.01ms !important;
  }

}
